<div class="d-flex justify-content-between align-items-center mb-4"><div><h1>Membership</h1><p class="text-muted">Your verified membership and payment position.</p></div><a class="btn btn-outline-primary" href="<?=e(url('/finance/invoices'))?>">Invoices</a></div>
<?php if(!$membership):?><div class="alert alert-info">No membership has been issued. An approved application is required first.</div><?php else:?><div class="card shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between align-items-start gap-3"><h2 class="h5"><?=e($membership['membership_number'])?></h2><?php if($membership['status']==='active'):?><a class="btn btn-sm btn-outline-primary" href="<?=e(url('/membership/certificate'))?>">View certificate</a><?php endif;?></div><dl class="row mb-0"><dt class="col-sm-4">Status</dt><dd class="col-sm-8"><?=e(str_replace('_',' ',$membership['status']))?></dd><dt class="col-sm-4">Application</dt><dd class="col-sm-8"><?=e($membership['application_number'])?></dd><dt class="col-sm-4">Type</dt><dd class="col-sm-8"><?=e($membership['membership_type_name'])?></dd></dl><?php if($membership['status']==='awaiting_fee_configuration'):?><div class="alert alert-warning mt-3 mb-0">Fee configuration pending. Your approved application is preserved, but membership is not active.</div><?php endif;?></div></div><?php endif;?>
<?php if($invoices):?><h2 class="h4">Invoices</h2><?php foreach($invoices as $i):?><a class="card card-body mb-2 text-decoration-none" href="<?=e(url('/finance/invoices/'.$i['invoice_number']))?>"><strong><?=e($i['invoice_number'])?></strong><span><?=e($i['currency'].' '.$i['balance_due'].' due — '.str_replace('_',' ',$i['status']))?></span></a><?php endforeach;?><?php endif;?>
